const idsPedido = (nodo) => { const m = {};
  for (const f of $(nodo).first().json.customFields || []) m[String(f.fieldKey || '').replace(/^opportunity\./, '')] = f.id;
  return m; };
const valor = (o, ids, clave) => { const x = (o.customFields || []).find(f => f.id === ids[clave]);
  if (!x) return null;
  const v = x.fieldValue ?? x.value ?? x.fieldValueString ?? x.fieldValueNumber ?? x.fieldValueArray ?? null;
  return Array.isArray(v) ? v[0] ?? null : v; };

// Los apartados vivos están en la etapa 3 (apartado) o en la 4 (liga enviada). Si expira_en
// viene vacío o no parsea, se ignora: mejor no liberar que liberar de más.
// ponytail: lee hasta 100 oportunidades abiertas del pipeline; si hay más, paginar.
const c = $('Config').first().json;
const etapas = [c.GHL_STAGE_APARTADO, c.GHL_STAGE_LIGA];
const ids = idsPedido('GHL · campos del pedido');
const ahora = Date.now();
const vencidos = [];
for (const o of $input.first().json.opportunities || []) {
  if (!etapas.includes(o.pipelineStageId)) continue;
  const leer = (k) => valor(o, ids, k);
  const expira = leer('expira_en');
  const estado = leer('estado_apartado');
  if (!expira || estado === 'pagado' || estado === 'vencido') continue;
  const t = Date.parse(expira);
  if (Number.isNaN(t) || t > ahora) continue;   // formato raro o todavía tiene tiempo
  vencidos.push({ opportunityId: o.id, contactId: o.contactId || (o.contact || {}).id,
    sku: leer('sku_apartado'), articulo: leer('articulo_apartado'),
    cantidad: Number(leer('cantidad_apartada') || 1), expira_en: expira });
}
return vencidos.map(v => ({ json: v }));

// Para cada vencido, encuentra su price en el inventario y calcula el stock devuelto.
const inv = $input.first().json.inventory || [];
const vencidos = $('¿Cuáles vencieron?').all().map(i => i.json);
const salida = [];
for (const v of vencidos) {
  const i = inv.find(x => (x.sku || '').trim() === (v.sku || '').trim());
  if (!i) continue;
  salida.push({ json: { ...v, productId: i.product, priceId: i._id, nuevoStock: Number(i.availableQuantity ?? 0) + Number(v.cantidad || 1) } });
}
return salida;
